#!/usr/bin/env node
/**
 * Publishes the site to the gh-pages branch and keeps a persistent list of PR previews.
 *
 *   push to main          → replace the site root, keep previews/
 *   PR opened/synchronize → previews/pr-<n>/ (fresh build), list entry, PR comment with the link
 *   PR edited             → refresh the list entry's title and summary
 *   PR closed             → mark the entry merged/closed; the preview itself is kept
 *
 * PR text is read from the event payload file, never interpolated into the workflow.
 * Pushes are retried on a fresh copy of gh-pages, so concurrent runs cannot lose each other's work.
 *
 * Env: GITHUB_EVENT_NAME, GITHUB_EVENT_PATH, GITHUB_REPOSITORY, GITHUB_TOKEN (for the comment),
 *      SITE_DIR (build output, default packages/ui/dist), PAGES_URL (optional override),
 *      PAGES_BRANCH (default gh-pages), DRY_COMMENT=1 to print the comment instead of posting.
 */
import { execFileSync } from 'node:child_process';
import { cpSync, existsSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, relative, resolve, sep } from 'node:path';

const env = process.env;
const eventName = env.GITHUB_EVENT_NAME ?? 'workflow_dispatch';
const event = env.GITHUB_EVENT_PATH ? JSON.parse(readFileSync(env.GITHUB_EVENT_PATH, 'utf8')) : {};
const [owner, repoName] = (env.GITHUB_REPOSITORY ?? 'owner/repo').split('/');
const pagesUrl = (env.PAGES_URL || `https://${owner.toLowerCase()}.github.io/${repoName}/`).replace(/\/?$/, '/');
const siteDir = resolve(env.SITE_DIR ?? 'packages/ui/dist');
const branch = env.PAGES_BRANCH ?? 'gh-pages';
const MARKER = '<!-- site-preview -->';

const pr = event.pull_request;
const mode = eventName === 'pull_request' && pr ? (event.action === 'closed' ? 'pr-closed' : event.action === 'edited' ? 'pr-edited' : 'pr-build') : 'main';

// ---------- helpers ----------

const git = (args, opts = {}) => execFileSync('git', args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], ...opts }).trim();

export const escapeHtml = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

/** First real paragraph of a PR body, as plain text, trimmed to ~240 characters. */
export function summarise(body) {
  const text = String(body ?? '')
    .replace(/\r/g, '')
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/```[\s\S]*?```/g, '');
  const paras = text.split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean);
  const para = paras.find((p) => !/^(#{1,6}\s|---|🤖|https?:\/\/\S+$|_Generated by)/.test(p)) ?? '';
  const plain = para
    .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
    .replace(/^\s*>\s?/gm, '')
    .replace(/\*\*|__|`/g, '')
    .replace(/^\s*[-+*]\s+/gm, '')
    .replace(/\s+/g, ' ')
    .trim();
  return plain.length > 240 ? plain.slice(0, 237).replace(/\s+\S*$/, '') + '…' : plain;
}

function walk(dir) {
  return readdirSync(dir).flatMap((n) => {
    const p = join(dir, n);
    return statSync(p).isDirectory() ? walk(p) : [p];
  });
}

/** Small fixed tab on every preview page linking back to the list. */
function injectRibbon(previewRoot, number) {
  for (const file of walk(previewRoot).filter((f) => f.endsWith('.html'))) {
    const depth = relative(previewRoot, file).split(sep).length - 1;
    const back = '../'.repeat(depth + 1);
    const tab =
      `<div data-preview-ribbon style="position:fixed;top:0;left:50%;transform:translateX(-50%);z-index:2147483647;` +
      `background:#1f2933;color:#fff;font:600 11px/1 system-ui,sans-serif;padding:4px 10px;border-radius:0 0 6px 6px;opacity:.9">` +
      `PR #${number} preview · <a href="${back}" style="color:#9cc9f5">all previews</a></div>`;
    const html = readFileSync(file, 'utf8');
    if (html.includes('data-preview-ribbon')) continue;
    writeFileSync(file, html.includes('</body>') ? html.replace('</body>', `${tab}\n</body>`) : html + tab);
  }
}

function placeholderPage(title, body) {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${escapeHtml(title)}</title><style>body{font:16px/1.6 system-ui,sans-serif;max-width:720px;margin:64px auto;padding:0 20px;color:#1f2933}</style>
</head><body><h1>${escapeHtml(title)}</h1>${body}</body></html>\n`;
}

/** Copy the build output into `dest`, or write a placeholder when there is none. */
function copySite(dest, fallbackTitle, fallbackBody) {
  mkdirSync(dest, { recursive: true });
  if (existsSync(siteDir) && readdirSync(siteDir).length) cpSync(siteDir, dest, { recursive: true });
  else writeFileSync(join(dest, 'index.html'), placeholderPage(fallbackTitle, fallbackBody));
}

// ---------- previews list ----------

const STATUS = { open: 'Open', merged: 'Merged', closed: 'Closed' };

export function renderIndex(entries, siteUrl) {
  const items = [...entries]
    .sort((a, b) => b.number - a.number)
    .map(
      (e) => `
    <li class="card ${e.status}">
      <div class="head">
        <a class="title" href="./pr-${e.number}/">#${e.number} · ${escapeHtml(e.title)}</a>
        <span class="badge">${STATUS[e.status] ?? escapeHtml(e.status)}</span>
      </div>
      ${e.summary ? `<p>${escapeHtml(e.summary)}</p>` : ''}
      <div class="meta">
        <a href="./pr-${e.number}/">Open preview</a> ·
        <a href="${escapeHtml(e.prUrl)}">View PR</a> ·
        ${escapeHtml(e.branch)} @ <code>${escapeHtml(String(e.sha).slice(0, 7))}</code> ·
        updated ${escapeHtml(String(e.updated).slice(0, 16).replace('T', ' '))} UTC
      </div>
    </li>`,
    )
    .join('');
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>PR previews</title>
<meta name="description" content="Persistent previews of pull requests, one per PR, rebuilt on every push.">
<style>
  :root { --ink:#1f2933; --muted:#6b7785; --line:#d5dbe1; --bg:#f6f7f9; --open:#22a05a; --merged:#6a4fb3; --closed:#9aa5b1; }
  * { box-sizing: border-box; }
  body { margin:0; background:var(--bg); color:var(--ink); font:16px/1.55 system-ui,-apple-system,'Segoe UI',Roboto,sans-serif; }
  main { max-width:860px; margin:0 auto; padding:48px 20px 64px; }
  h1 { margin:0 0 4px; font-size:30px; }
  .lede { color:var(--muted); margin:0 0 24px; }
  ul { list-style:none; margin:0; padding:0; display:grid; gap:12px; }
  .card { background:#fff; border:1px solid var(--line); border-left:4px solid var(--closed); border-radius:8px; padding:14px 16px; }
  .card.open { border-left-color:var(--open); } .card.merged { border-left-color:var(--merged); }
  .head { display:flex; gap:12px; align-items:baseline; justify-content:space-between; }
  .title { font-weight:650; color:var(--ink); text-decoration:none; } .title:hover { text-decoration:underline; }
  .badge { font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.06em; color:#fff; background:var(--closed); padding:2px 8px; border-radius:3px; white-space:nowrap; }
  .open .badge { background:var(--open); } .merged .badge { background:var(--merged); }
  p { margin:6px 0; }
  .meta { color:var(--muted); font-size:13px; } .meta a { color:inherit; }
  code { font-size:12px; }
  .empty { color:var(--muted); }
</style>
</head>
<body>
<main>
  <p><a href="../">← Back to the site</a></p>
  <h1>PR previews</h1>
  <p class="lede">One preview per pull request, rebuilt on every push and kept after the PR closes. Newest first.</p>
  ${entries.length ? `<ul>${items}\n  </ul>` : '<p class="empty">No previews yet.</p>'}
  <p class="meta">Live site: <a href="${escapeHtml(siteUrl)}">${escapeHtml(siteUrl)}</a></p>
</main>
</body>
</html>
`;
}

function readEntries(root) {
  const f = join(root, 'previews', 'previews.json');
  return existsSync(f) ? JSON.parse(readFileSync(f, 'utf8')) : [];
}

function writeEntries(root, entries) {
  const dir = join(root, 'previews');
  mkdirSync(dir, { recursive: true });
  const sorted = [...entries].sort((a, b) => b.number - a.number);
  writeFileSync(join(dir, 'previews.json'), JSON.stringify(sorted, null, 2) + '\n');
  writeFileSync(join(dir, 'index.html'), renderIndex(sorted, pagesUrl));
}

function upsert(entries, patch) {
  const i = entries.findIndex((e) => e.number === patch.number);
  if (i >= 0) entries[i] = { ...entries[i], ...patch };
  else entries.push(patch);
  return entries;
}

// ---------- the change each mode makes to a gh-pages checkout ----------

function apply(root) {
  const now = new Date().toISOString();
  if (mode === 'main') {
    for (const n of readdirSync(root)) if (!['.git', 'previews', '.nojekyll'].includes(n)) rmSync(join(root, n), { recursive: true, force: true });
    copySite(root, 'Argonautical', `<p>The site has no build output yet.</p><p><a href="./previews/">PR previews</a></p>`);
    writeFileSync(join(root, '.nojekyll'), '');
    writeEntries(root, readEntries(root));
    return `Publish site from ${String(env.GITHUB_SHA ?? '').slice(0, 7) || 'main'}`;
  }
  const entries = readEntries(root);
  const n = pr.number;
  if (mode === 'pr-build') {
    const dest = join(root, 'previews', `pr-${n}`);
    rmSync(dest, { recursive: true, force: true });
    copySite(dest, `PR #${n} preview`, `<p>This pull request produced no site build output.</p>`);
    injectRibbon(dest, n);
    // A late build must not reopen a PR that a 'closed' run has already marked merged/closed.
    const prior = entries.find((e) => e.number === n);
    const status = prior && prior.status !== 'open' && event.action === 'synchronize' ? prior.status : 'open';
    upsert(entries, {
      number: n,
      title: pr.title,
      summary: summarise(pr.body),
      prUrl: pr.html_url,
      branch: pr.head?.ref ?? '',
      sha: pr.head?.sha ?? '',
      author: pr.user?.login ?? '',
      status,
      updated: now,
    });
  } else if (mode === 'pr-edited') {
    if (!entries.some((e) => e.number === n)) return null;
    upsert(entries, { number: n, title: pr.title, summary: summarise(pr.body) });
  } else if (mode === 'pr-closed') {
    if (!entries.some((e) => e.number === n)) return null;
    upsert(entries, { number: n, status: pr.merged ? 'merged' : 'closed', updated: now });
  }
  writeFileSync(join(root, '.nojekyll'), '');
  writeEntries(root, entries);
  return `Preview PR #${n}: ${mode.replace('pr-', '')}`;
}

// ---------- gh-pages checkout, commit, push with retry ----------

function publish() {
  git(['config', 'user.name', 'github-actions[bot]']);
  git(['config', 'user.email', '41898282+github-actions[bot]@users.noreply.github.com']);
  const work = mkdtempSync(join(env.RUNNER_TEMP || tmpdir(), 'gh-pages-'));
  for (let attempt = 1; attempt <= 5; attempt++) {
    rmSync(work, { recursive: true, force: true });
    try {
      git(['worktree', 'prune']);
    } catch {}
    let exists = true;
    try {
      git(['fetch', '--depth=1', 'origin', `+refs/heads/${branch}:refs/remotes/origin/${branch}`]);
    } catch {
      exists = false;
    }
    if (exists) {
      git(['worktree', 'add', '--detach', work, `origin/${branch}`]);
    } else {
      git(['worktree', 'add', '--detach', work]);
      git(['checkout', '--orphan', `${branch}-new`], { cwd: work });
      git(['rm', '-rf', '--quiet', '--ignore-unmatch', '.'], { cwd: work });
      git(['clean', '-fdxq'], { cwd: work });
    }
    try {
      const message = apply(work);
      if (!message) return console.log('Nothing to update (no preview entry for this PR).'), false;
      git(['add', '-A'], { cwd: work });
      if (!git(['status', '--porcelain'], { cwd: work })) return console.log('No changes to publish.'), true;
      git(['commit', '-q', '-m', message], { cwd: work });
      try {
        git(['push', 'origin', `HEAD:refs/heads/${branch}`], { cwd: work });
        console.log(`Published (${message}) on attempt ${attempt}.`);
        return true;
      } catch (e) {
        console.warn(`Push rejected on attempt ${attempt}; retrying on a fresh copy of ${branch}.\n${e.stderr ?? e}`);
      }
    } finally {
      git(['worktree', 'remove', '--force', work]);
    }
    execFileSync('sleep', [String(attempt * 2)]);
  }
  throw new Error(`Could not push to ${branch} after 5 attempts`);
}

// ---------- PR comment (one per PR, updated in place) ----------

async function comment() {
  const n = pr.number;
  const url = `${pagesUrl}previews/pr-${n}/`;
  const body =
    `${MARKER}\n**Preview:** ${url}\n\n` +
    `Built from \`${String(pr.head.sha).slice(0, 7)}\` · all previews: ${pagesUrl}previews/\n\n` +
    `<sub>Rebuilt on every push and kept after the PR closes. GitHub Pages can take a minute or two to update.</sub>`;
  if (env.DRY_COMMENT === '1' || !env.GITHUB_TOKEN) return console.log(`[comment]\n${body}`);
  const api = `https://api.github.com/repos/${owner}/${repoName}`;
  const headers = { Authorization: `Bearer ${env.GITHUB_TOKEN}`, Accept: 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28' };
  const list = await (await fetch(`${api}/issues/${n}/comments?per_page=100`, { headers })).json();
  const mine = Array.isArray(list) ? list.find((c) => c.body?.startsWith(MARKER)) : undefined;
  const res = await fetch(mine ? `${api}/issues/comments/${mine.id}` : `${api}/issues/${n}/comments`, {
    method: mine ? 'PATCH' : 'POST',
    headers,
    body: JSON.stringify({ body }),
  });
  if (!res.ok) throw new Error(`Comment failed: ${res.status} ${await res.text()}`);
  console.log(`${mine ? 'Updated' : 'Posted'} preview comment on PR #${n}.`);
}

if (process.argv[1] && resolve(process.argv[1]) === resolve(new URL(import.meta.url).pathname)) {
  console.log(`Mode: ${mode}; site dir: ${siteDir}; pages: ${pagesUrl}`);
  const published = publish();
  if (published && mode === 'pr-build') await comment();
}
